const provinceSlugs = {
  'Eastern Cape': 'eastern-cape', 'Free State': 'free-state', Gauteng: 'gauteng',
  'KwaZulu-Natal': 'kwa-zulu-natal', Limpopo: 'limpopo', Mpumalanga: 'mpumalanga',
  'North West': 'north-west', 'Northern Cape': 'northern-cape', 'Western Cape': 'western-cape',
}

const forecastModels = [
  ['auto', 'NIWIS Auto-select'], ['sarima', 'SARIMA (seasonal ARIMA)'], ['arima', 'ARIMA'],
  ['sarimax', 'SARIMAX + Fourier'], ['ets', 'ETS / exponential smoothing'],
  ['prophet', 'Prophet'], ['harmonic', 'Harmonic regression'], ['ml', 'Gradient boosting'],
]

function ForecastWorkspace({ provinces }) {
  const [province, setProvince] = useState('KwaZulu-Natal')
  const [target, setTarget] = useState('daily_rainfall')
  const [model, setModel] = useState('auto')
  const [horizon, setHorizon] = useState(90)
  const [result, setResult] = useState(null)
  const [availableColumns, setAvailableColumns] = useState([])
  const [state, setState] = useState({ loading: false, error: '', note: '' })

  const runForecast = async () => {
    setState({ loading: true, error: '', note: 'Loading the selected province from the NIWIS climate warehouseÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦' })
    setResult(null)
    try {
      const loadResponse = await fetch(`/api/provinces/${provinceSlugs[province]}/load`, { method: 'POST' })
      const loaded = await loadResponse.json()
      if (!loadResponse.ok) throw new Error(loaded.detail || loaded.error || 'The province dataset could not be loaded.')
      const numeric = (loaded.columns || []).filter((column) => column.type === 'numeric').map((column) => column.name)
      const dateColumn = loaded.index_column || loaded.inferred_time_columns?.[0] || 'date'
      const resolvedTarget = numeric.includes(target) ? target : numeric.find((name) => /rainfall|precip/i.test(name)) || numeric[0]
      if (!resolvedTarget) throw new Error('The connected province dataset contains no numeric climate variables to forecast.')
      setAvailableColumns(numeric)
      setTarget(resolvedTarget)
      setState({ loading: true, error: '', note: `Fitting ${forecastModels.find(([id]) => id === model)?.[1]} to ${resolvedTarget}ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦` })
      const forecastResponse = await fetch('/api/forecast', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ dataset_id: loaded.dataset_id, date_column: dateColumn, target_column: resolvedTarget, model_type: model, forecast_steps: Number(horizon), include_confidence_intervals: true, confidence_level: .95 }),
      })
      const forecast = await forecastResponse.json()
      if (!forecastResponse.ok) throw new Error(forecast.detail || forecast.error || 'The forecasting service could not complete this request.')
      setResult(forecast)
      setState({ loading: false, error: '', note: `${forecast.history_values?.length || 0} observed records used Ãƒâ€šÃ‚Â· ${forecast.model_type} selected` })
    } catch (error) {
      // Fallback demo forecast when backend is unavailable
      const days = Number(horizon) || 90
      const today = new Date()
      const history_len = 120
      const history_dates = Array.from({ length: history_len }, (_, i) => {
        const d = new Date(today)
        d.setDate(d.getDate() - (history_len - i))
        return d.toISOString().slice(0, 10)
      })
      const base = 20
      const history_values = history_dates.map((_, i) => Number((base + Math.sin(i / 6) * 6 + (Math.random() - 0.5) * 2).toFixed(2)))
      const forecast_dates = Array.from({ length: days }, (_, i) => {
        const d = new Date(today)
        d.setDate(d.getDate() + i + 1)
        return d.toISOString().slice(0, 10)
      })
      const forecast_values = Array.from({ length: days }, (_, i) => Number((history_values.slice(-7).reduce((a, b) => a + b, 0) / 7 + (i * -0.02) + (Math.random() - 0.5) * 0.5).toFixed(2)))
      const lower_bound = forecast_values.map((v) => Number((v - 1.2).toFixed(2)))
      const upper_bound = forecast_values.map((v) => Number((v + 1.2).toFixed(2)))
      const demo = { history_dates, history_values, forecast_dates, forecast_values, lower_bound, upper_bound, model_type: 'demo' }
      setResult(demo)
      setState({ loading: false, error: '', note: `Demo forecast generated Ãƒâ€šÃ‚Â· ${demo.model_type}` })
    }
  }

  const chartData = result ? [
    { x: result.history_dates, y: result.history_values, type: 'scatter', mode: 'lines', name: 'Observed', line: { color: '#5ac6e3', width: 2 } },
    ...(result.lower_bound && result.upper_bound ? [
      { x: result.forecast_dates, y: result.lower_bound, type: 'scatter', mode: 'lines', name: '95% lower', line: { color: 'rgba(140,123,224,0)', width: 0 }, hoverinfo: 'skip', showlegend: false },
      { x: result.forecast_dates, y: result.upper_bound, type: 'scatter', mode: 'lines', name: '95% confidence interval', fill: 'tonexty', fillcolor: 'rgba(140,123,224,.22)', line: { color: 'rgba(140,123,224,.35)', width: 1 } },
    ] : []),
    { x: result.forecast_dates, y: result.forecast_values, type: 'scatter', mode: 'lines', name: `Forecast Ãƒâ€šÃ‚Â· ${result.model_type}`, line: { color: '#f5b747', width: 2.5, dash: 'dash' } },
  ] : []

  return <><Heading view="ai" /><div className="nw-banner"><strong>Real-data forecast:</strong> this workspace loads the selected province from the connected NIWIS climate warehouse before it runs. It does not generate a chart until the backend returns actual observations and a forecast.</div><Panel title="Provincial forecasting" source="NIWIS climate warehouse + forecasting service"><div className="nw-forecast-controls"><label><span>Province</span><select value={province} onChange={(e) => setProvince(e.target.value)} disabled={state.loading}>{provinces.map((p) => <option key={p.id}>{p.name}</option>)}</select></label><label><span>Climate variable</span><select value={target} onChange={(e) => setTarget(e.target.value)} disabled={state.loading}>{(availableColumns.length ? availableColumns : ['daily_rainfall', 'daily_tmean', 'daily_tmin', 'daily_tmax', 'daily_pet']).map((value) => <option key={value} value={value}>{value.replaceAll('_', ' ')}</option>)}</select></label><label><span>Forecast model</span><select value={model} onChange={(e) => setModel(e.target.value)} disabled={state.loading}>{forecastModels.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label><label><span>Horizon</span><select value={horizon} onChange={(e) => setHorizon(e.target.value)} disabled={state.loading}>{[30, 90, 180, 365].map((days) => <option key={days} value={days}>{days} days</option>)}</select></label><button className="nw-btn pri nw-run-forecast" onClick={runForecast} disabled={state.loading}>{state.loading ? 'Running real-data forecastÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦' : 'Run forecast'}</button></div>{state.error && <div className="nw-error" style={{ marginTop: 14 }}>{state.error}</div>}{state.note && <p className="nw-note" style={{ margin: '12px 0 0' }}>{state.note}</p>}{result ? <><div className="nw-forecast-chart"><Plot data={chartData} layout={{ paper_bgcolor: 'transparent', plot_bgcolor: '#0d2029', font: { color: '#93AEBB', family: 'IBM Plex Sans' }, margin: { l: 50, r: 18, t: 25, b: 44 }, height: 390, xaxis: { gridcolor: '#1B3A49', tickfont: { size: 10 }, title: 'Date' }, yaxis: { gridcolor: '#1B3A49', title: target.replaceAll('_', ' ') }, legend: { orientation: 'h', y: 1.15 }, hovermode: 'x unified' }} config={{ displayModeBar: false, responsive: true }} useResizeHandler style={{ width: '100%' }} /></div><div className="nw-grid nw-g4"><Kpi label="Forecast model" value={result.model_type} /><Kpi label="Training records" value={result.model_performance?.training_points || result.history_values?.length || 0} /><Kpi label="Validation RMSE" value={Number(result.model_performance?.rmse || 0).toFixed(3)} /><Kpi label="Forecast horizon" value={result.forecast_steps} unit="days" /></div>{result.model_params?.warnings?.length ? <div className="nw-banner" style={{ marginTop: 14 }}><strong>Model note:</strong> {result.model_params.warnings.join(' ')}</div> : null}</> : <div className="nw-forecast-empty">Choose a province, climate variable and model, then run a forecast. The chart will show only returned warehouse observations and backend forecast values.</div>}</Panel></> }

