  runoff: { title: 'Runoff monitoring', intro: 'Indicative river-flow conditions from the national gauging network.', cols: ['Station', 'Flow', 'Percentile', 'State'], rows: STATIONS.map((s) => [s.n, `${s.q} mÃƒâ€šÃ‚Â³/s`, `${s.pct}%`, s.state]) },
