  rwqo: { title: 'Resource quality objectives', intro: 'Resource-quality objective categories for managed water systems.', cols: ['Objective', 'Measure', 'Application', 'State'], rows: [['Ecological reserve', 'Flow and quality bands', 'Catchment allocation', 'Catalogue available'], ['Domestic use', 'SANS 241 thresholds', 'Water services', 'Catalogue available'], ['Irrigation use', 'Salinity and microbial load', 'Agriculture', 'Catalogue available']] },
