  tariffs: { title: 'Raw water tariffs', intro: 'Indicative charges by national water-resource scheme.', cols: ['Scheme', 'Raw water', 'Annual change', 'Users'], rows: TARIFFS.map((s) => [s.sch, `R ${s.raw.toFixed(2)}/mÃƒâ€šÃ‚Â³`, `${s.d}%`, s.users]) },
