function CatalogueView({ view }) {
  const item = catalogue[view]
  const title = item?.title || view.replace(/\b\w/g, (letter) => letter.toUpperCase())
  const rows = item?.rows || [['Operational data connection', 'Pending', 'ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â', 'Available in future feed']]
  const cols = item?.cols || ['Module', 'State', 'Last update', 'Next action']
  return <><Heading view={view} /><Panel title={title} source="NIWIS catalogue"><p className="nw-psub">{item?.intro || 'This operational module is represented in the NIWIS prototype catalogue.'}</p><div className="nw-tscroll"><table><thead><tr>{cols.map((col) => <th key={col}>{col}</th>)}</tr></thead><tbody>{rows.map((row, i) => <tr key={`${row[0]}-${i}`}>{row.map((cell, j) => <td key={j}>{cell}</td>)}</tr>)}</tbody></table></div></Panel></>
}

function Studio({ studio, setStudio }) {
  const views = {
    timeseries: ['Time series', TimeSeriesDashboard],
    forecast: ['Forecasting studio', ForecastingWorkspace],
    spatial: ['Spatial analysis', SpatialAnalysis],
    multivariate: ['Multivariate statistics', MultivariateStatistics],
  }
  const Active = views[studio][1]
  return <><Heading view="studio" /><div className="nw-chips">{Object.entries(views).map(([id, [label]]) => <button key={id} className={`nw-chip ${studio === id ? 'sel' : ''}`} onClick={() => setStudio(id)}>{label}</button>)}</div><div className="nw-banner"><strong>Integrated system:</strong> this is the existing analysis application running inside the new NIWIS portal. Forecasting studio defaults to LSTM with target spi_3.</div><div className={studio === 'forecast' ? 'nw-studio-light' : undefined}><Active /></div></>
}

export default function NIWISPortal() {
  const [entered, setEntered] = useState(true), [view, setViewState] = useState(viewFromLocation), [navOpen, setNavOpen] = useState(false), [selected, setSelected] = useState('GP'), [predictions, setPredictions] = useState([]), [studio, setStudio] = useState('forecast')
  const [expandedGroups, setExpandedGroups] = useState({})
    const [regionMeteo, setRegionMeteo] = useState([])
  const setView = (nextView) => {
    setViewState(nextView)
    if (typeof window !== 'undefined') {
      const nextPath = VIEW_ROUTES[nextView] || '/drought'
      if (window.location.pathname !== nextPath) window.history.pushState({ view: nextView }, '', nextPath)
    }
  }
  useEffect(() => {
    const onPopState = () => setViewState(viewFromLocation())
    window.addEventListener('popstate', onPopState)
    // Make the default dashboard address explicit while keeping the existing
    // root entry point working for bookmarks and local development.
    if (window.location.pathname === '/') window.history.replaceState({ view: 'monitoring' }, '', '/drought')
    return () => window.removeEventListener('popstate', onPopState)
  }, [])
  useEffect(() => { document.body.classList.add('nw-body'); return () => document.body.classList.remove('nw-body') }, [])
  useEffect(() => {
    // Every module is a new dashboard context. Do not leave the user halfway
    // down the previous module when a navigation item is selected.
    window.scrollTo({ top: 0, left: 0, behavior: 'auto' })
  }, [view])
  useEffect(() => { fetch('/niwis-api/api/predictions/latest').then((r) => r.ok ? r.json() : Promise.reject()).then((r) => setPredictions(r.predictions || [])).catch(() => {}) }, [])
  const provinces = useMemo(() => liveProvinces(predictions), [predictions])
  const selectProvince = (id) => { setSelected(id); setView('drought') }
  const selectSatelliteProvince = (id) => setSelected(id)
  const content = view === 'groundwater' ? <GroundwaterLevelMonitoring /> : view === 'groundwater-reserve' ? <GroundwaterReserveAssessment /> : view === 'water-quality' ? <WaterQualityMonitoring /> : view === 'surface' ? <SurfaceWaterNetwork /> : view === 'runoff' ? <RunoffStatus /> : view === 'rainfall' ? <RainfallStatus /> : view === 'vegetation' ? <VegetationCondition /> : (view === 'climate' || view.startsWith('climate-')) ? <ClimateDashboard key={`climate-dashboard-${view}`} section={view.startsWith('climate-') ? view.slice(8) : null} /> : view === 'monitoring' ? <DroughtMonitoring renderForecast={(region) => <DeferredPanel key={region}><OverviewForecastStudio region={region} /></DeferredPanel>} /> : view === 'overview' ? <MeteorologicalDrought renderForecast={(region) => <DeferredPanel key={region}><OverviewForecastStudio region={region} /></DeferredPanel>} /> : view === 'drought' ? <Drought provinces={provinces} selected={selected} selectProvince={selectProvince} /> : view === 'alerts' ? <Alerts /> : view === 'dams' ? <ReservoirStatus /> : view === 'ai' ? <Prediction /> : view === 'pipeline' ? <Pipeline /> : view === 'roadmap' ? <RoadmapView /> : view === 'satellite' ? <Satellite provinces={provinces} selected={selected} selectProvince={selectSatelliteProvince} /> : view === 'hydrology' ? <HydrologyDrought /> : view === 'studio' ? <Studio studio={studio} setStudio={setStudio} /> : <CatalogueView view={view} />
  // Water quality remains scoped to its monitoring page. Vegetation also
  // exposes the shared forecasting studio with its compact source endpoint.
  const forecastDashboard = view.startsWith('climate') ? 'climate' : ({ vegetation: 'vegetation', rainfall: 'rainfall', runoff: 'runoff', surface: 'surface', groundwater: 'groundwater', 'groundwater-reserve': 'groundwater-reserve', satellite: 'satellite', hydrology: 'hydrology' }[view] || null)
  const forecastSection = view.startsWith('climate-') ? view.slice(8) : null
  if (!entered) return <div className="nw nw-unified-theme"><div className="nw-gate"><div className="nw-gate-card"><div className="nw-gate-left"><div className="nw-crest"><img className="nw-logo" src="/Water-and-Sanitation.png" alt="Department of Water and Sanitation logo" /><div><b>NIWIS</b><div className="nw-note">Department of Water and Sanitation</div></div></div><h1 className="nw-gate-title">National Integrated Water Information System</h1><p className="nw-gate-sub">One view of South AfricaÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢s water: rainfall, dams, rivers, groundwater, quality and services ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â updated continuously and forecast ahead.</p><div className="nw-role-list">{ROLES.map((r) => <button className="nw-role" key={r.id} onClick={() => setEntered(true)}><i className="nw-role-key">{r.k}</i><div><b>{r.n}</b><span>{r.d}</span></div></button>)}</div><p className="nw-gate-note">Prototype portal. Live climate and prediction data are shown where the connected NIWIS service is available.</p></div><div className="nw-gate-right"><div className="nw-note">Platform status ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â 15 Sep 2026, 06:00 SAST</div>{[['Data sources registered', `${SOURCES.length}`], ['Telemetry stations reporting', '4 118'], ['Records ingested, last 24 h', '12.4 M'], ['Forecast models in production', '1'], ['Open alerts', '17']].map(([l, v]) => <div className="nw-gate-stat" key={l}><span>{l}</span><b className="mono">{v}</b></div>)}</div></div></div></div>
    return <div className="nw nw-unified-theme"><div className={`nw-app ${view === 'monitoring' ? 'dm-shell' : (view === 'climate' || view.startsWith('climate-')) ? 'climate-shell' : view === 'vegetation' ? 'climate-shell vegetation-shell' : view === 'rainfall' ? 'climate-shell rainfall-shell' : view === 'runoff' ? 'climate-shell runoff-shell' : view === 'surface' ? 'climate-shell surface-water-shell' : view === 'groundwater' ? 'climate-shell groundwater-shell' : view === 'groundwater-reserve' ? 'climate-shell groundwater-reserve-shell' : view === 'water-quality' ? 'climate-shell water-quality-shell' : view === 'dams' ? 'climate-shell reservoir-shell' : ''}`}><header className="nw-topbar"><button className="nw-iconbtn" onClick={() => setNavOpen(!navOpen)} aria-label="Toggle menu"><Menu size={16} /></button><div className="nw-brand"><img className="nw-logo nw-logo-topbar" src="/Water-and-Sanitation.png" alt="Department of Water and Sanitation logo" /> NIWIS</div>{view === 'groundwater' ? <div className="nw-statusstrip"><div className="nw-sstat"><em>GROUNDWATER LEVEL NETWORK</em><b>Levels / Recharge / Aquifers</b></div><div className="nw-sstat"><em>COVERAGE</em><b>52 districts</b></div></div> : view === 'groundwater-reserve' ? <div className="nw-statusstrip"><div className="nw-sstat"><em>GROUNDWATER RESERVE ASSESSMENT</em><b>Recharge / Abstraction / Storage</b></div><div className="nw-sstat"><em>COVERAGE</em><b>52 districts</b></div></div> : view === 'water-quality' ? <div className="nw-statusstrip"><div className="nw-sstat"><em>WATER QUALITY MONITORING</em><b>Physical / Chemical / Biological / SANSA</b></div><div className="nw-sstat"><em>COVERAGE</em><b>52 districts</b></div></div> : view === 'dams' ? <div className="nw-statusstrip"><div className="nw-sstat"><em>DAM AND RESERVOIR STATUS</em><b>Storage / Releases / Catchment conditions</b></div><div className="nw-sstat"><em>SOURCE</em><b>Supabase table: 8_1_reservoir_operational_master</b></div></div> : view === 'surface' ? <div className="nw-statusstrip"><div className="nw-sstat"><em>SURFACE WATER NETWORK</em><b>Hydrology / Catchments / Earth observation</b></div><div className="nw-sstat"><em>COVERAGE</em><b>52 districts</b></div></div> : view === 'runoff' ? <div className="nw-statusstrip"><div className="nw-sstat"><em>RUNOFF STATUS</em><b>Catchment response / Flows / Water balance</b></div><div className="nw-sstat"><em>COVERAGE</em><b>52 districts</b></div></div> : view === 'rainfall' ? <div className="nw-statusstrip"><div className="nw-sstat"><em>RAINFALL STATUS</em><b>Observations / Satellite estimates / Indices</b></div><div className="nw-sstat"><em>COVERAGE</em><b>52 districts</b></div></div> : view === 'vegetation' ? <div className="nw-statusstrip"><div className="nw-sstat"><em>VEGETATION CONDITION</em><b>Satellite indices / Climate drivers</b></div><div className="nw-sstat"><em>COVERAGE</em><b>52 districts</b></div></div> : (view === 'climate' || view.startsWith('climate-')) ? <div className="nw-statusstrip"><div className="nw-sstat"><em>CLIMATE DASHBOARD</em><b>Six connected climate datasets</b></div><div className="nw-sstat"><em>COVERAGE</em><b>52 districts</b></div></div> : view === 'monitoring' ? <div className="nw-statusstrip"><div className="nw-sstat"><em>DROUGHT MONITORING</em><b>Climate / Water / Vegetation</b></div><div className="nw-sstat"><em>DATA SOURCE</em><b>Supabase observations</b></div></div> : (<div className="nw-statusstrip"><div className="nw-sstat"><em>NATIONAL DROUGHT</em><b>D2 Ãƒâ€šÃ‚Â· Severe</b></div><div className="nw-sstat"><em>CONNECTED DATA</em><b>{predictions.length ? 'Climate predictions' : 'Demo fallback'}</b></div></div>)}<div className="nw-topactions"><span className="nw-pill live"><i className="nw-dot" />{(view === 'climate' || view.startsWith('climate-')) ? 'Supabase observations' : view === 'vegetation' ? 'Supabase observations' : view === 'rainfall' ? 'Supabase observations' : view === 'runoff' ? 'Runoff files' : view === 'surface' ? 'Supabase observations' : view === 'groundwater' ? 'Supabase observations' : view === 'groundwater-reserve' ? 'Supabase observations' : view === 'water-quality' ? 'Supabase observations' : view === 'dams' ? 'Supabase observations' : 'Live'}</span><button className="nw-iconbtn" onClick={() => setEntered(false)}><SlidersHorizontal size={15} /></button></div></header><nav className={`nw-nav ${navOpen ? 'open' : ''}`}>{NAV.map(([group, items]) => <div key={group}><div className="nw-navgroup">{group}</div>{items.map(([id, label, num, live, children]) => {
    const groupOpen = !!expandedGroups[id]
    const active = view === id || children?.some(([childId]) => childId === view) || (id === 'monitoring' && view === 'drought')
    return <div key={id}>
      <button className={`nw-navitem ${active ? 'sel' : ''}`} aria-expanded={children ? groupOpen : undefined} aria-controls={children ? `nw-${id}-subgroups` : undefined} onClick={() => {
        if (children) { setExpandedGroups(current => ({ ...current, [id]: !current[id] })); setView(id) }
        else { setView(id); setNavOpen(false) }
      }}>{num && <span className="nw-nid">{num}.</span>}<span className="nw-nav-label">{label}</span>{live && <span className="nw-live">Live</span>}{children && <ChevronDown size={16} className={`nw-nav-chevron ${groupOpen ? 'expanded' : ''}`} />}</button>
      {children && groupOpen && <div id={`nw-${id}-subgroups`} className="nw-nav-subgroups">{children.map(([childId, childLabel]) => <button key={childId} className={`nw-navitem nw-nav-child ${view === childId ? 'sel' : ''}`} onClick={() => { setView(childId); setNavOpen(false) }}>{childLabel}</button>)}</div>}
    </div>
  })}</div>)}<div className="nw-nav-brand-card"><div className="nw-brand-water-icon">ÃƒÂ°Ã…Â¸Ã¢â‚¬â„¢Ã‚Â§</div><div className="nw-brand-tagline"><strong>Reliable Water Data.</strong><span>Informed Decisions.</span><em>A Resilient South Africa.</em></div></div></nav><main className="nw-main"><DataFreshness view={view} /><Suspense fallback={<LoadingProgress message="Loading dashboard" />}>{content}</Suspense>{forecastDashboard && <DeferredPanel key={`deferred-${forecastDashboard}-${forecastSection || 'all'}`}><DashboardForecastStudio key={`forecast-${forecastDashboard}-${forecastSection || 'all'}`} dashboard={forecastDashboard} section={forecastSection} /></DeferredPanel>}</main></div></div>
}
